insert into public.hard_sector_sections(sector,section_key,body) values('realestate','seo','{"portal":{"pageId":"portal","title":{"en":"HARD Group","ar":"مجموعة هارد"},"description":{"en":"HARD Group - Unified multi-sector platform for Real Estate Brokerage, General Contracting, and Enterprise HVAC Solutions in Saudi Arabia.","ar":"مجموعة هارد - البوابة الموحدة لقطاعات التطوير والوساطة العقارية، المقاولات العامة، وأنظمة التكييف بالمملكة العربية السعودية."},"ogImage":"https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=80","indexable":true,"canonicalPath":"/"},"home":{"pageId":"home","title":{"en":"HARD Real Estate | Certified Saudi Brokerage & Investment","ar":"هارد للعقارات | الوساطة والاستثمار العقاري المعتمد"},"description":{"en":"HARD Real Estate - REGA certified real estate marketing and luxury property acquisitions across Al Khobar, Riyadh, and Eastern Province.","ar":"شركة هارد للعقارات - منصة تسويق ووساطة عقارية معتمدة من الهيئة العامة للعقار (فال)، متخصصة بالفلل الفاخرة والأراضي بالشرقية والرياض."},"ogImage":"https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=80","indexable":true,"canonicalPath":"/realestate"},"properties":{"pageId":"properties","title":{"en":"Luxury Properties For Sale & Rent | HARD Real Estate","ar":"العقارات والفلل المتاحة للبيع والإيجار | هارد للعقارات"},"description":{"en":"Browse verified luxury villas, sea-view apartments, townhouses, and commercial assets available for sale and rent in Saudi Arabia.","ar":"استعرض أحدث العقارات الموثقة، الفلل الملكية، والشقق المتاحة للبيع والإيجار بأسعار محدثة وضمانات رسمية."},"ogImage":"https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=1200&q=80","indexable":true,"canonicalPath":"/realestate/properties"},"projects":{"pageId":"projects","title":{"en":"Master Off-Plan Developments | HARD Real Estate","ar":"المشاريع التطويرية والواجهات البحرية | هارد للعقارات"},"description":{"en":"Explore prime residential and commercial master developments in Al Khobar and Riyadh with official escrow guarantees.","ar":"استكشف كبرى المشاريع التطويرية السكنية والتجارية مع خطط سداد مرنة وضمانات حسابات الضمان المعتمدة."},"ogImage":"https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&w=1200&q=80","indexable":true,"canonicalPath":"/realestate/projects"},"marketing":{"pageId":"marketing","title":{"en":"Real Estate Marketing & Asset Advisory | HARD Group","ar":"التسويق والوساطة العقارية | هارد للعقارات"},"description":{"en":"Professional asset evaluation, luxury marketing campaigns, and REGA-compliant transaction closing.","ar":"خدمات التقييم والتسويق العقاري الاحترافي للأصول الفاخرة والمحافِظ الاستثمارية مع توثيق إلكتروني معتمد."},"ogImage":"https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1200&q=80","indexable":true,"canonicalPath":"/realestate/marketing"},"about":{"pageId":"about","title":{"en":"About HARD Real Estate & Group Holding","ar":"من نحن والعقلية التطويرية | هارد للعقارات"},"description":{"en":"Pioneering Saudi real estate development, general contracting, and engineering excellence.","ar":"تعرف على رؤية وقيم مجموعة هارد وإنجازاتها التنموية في قطاعات العقار والبناء والتكييف بالمملكة."},"ogImage":"https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1200&q=80","indexable":true,"canonicalPath":"/realestate/about"},"blog":{"pageId":"blog","title":{"en":"Saudi Real Estate Market Reports & Articles | HARD","ar":"المدونة والتقارير العقارية | هارد للعقارات"},"description":{"en":"Expert market analysis on Saudi property investment trends, rental yields, and REGA regulatory frameworks.","ar":"تقارير ودراسات تحليليية لحركة أداء السوق العقاري السعودي وفرص الاستثمار بالمنطقة الشرقية والرياض."},"ogImage":"https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1200&q=80","indexable":true,"canonicalPath":"/realestate/blog"},"contact":{"pageId":"contact","title":{"en":"Contact Senior Advisors | HARD Real Estate","ar":"تواصل مع مستشارينا | هارد للعقارات"},"description":{"en":"Connect with HARD Group offices in Al Khobar, Riyadh, and Dammam for inquiries and private viewings.","ar":"تواصل مباشر مع فروع مجموعة هارد بالخبر والرياض والدمام لاستشارات الاستثمار وحجز المعاينات."},"ogImage":"https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1200&q=80","indexable":true,"canonicalPath":"/realestate/contact"},"construction":{"pageId":"construction","title":{"en":"HARD Contracting","ar":"هارد للمقاولات"},"description":{"en":"General contracting and construction in the Eastern Province, delivering commercial and residential projects with Saudi Building Code compliance.","ar":"هارد للمقاولات العامة والإنشائية في المنطقة الشرقية لتنفيذ المشاريع التجارية والسكنية وفق كود البناء السعودي."},"ogImage":"https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&w=1200&q=80","indexable":true,"canonicalPath":"/construction"},"hvac":{"pageId":"hvac","title":{"en":"HARD HVAC Maintenance","ar":"هارد لصيانة التكييف"},"description":{"en":"Professional air conditioning maintenance, central HVAC systems and VRF services in the Eastern Province.","ar":"حلول التكييف المركزي والمياه المثلجة وأنظمة VRF والخدمات الكهروميكانيكية الطارئة للمنشآت."},"ogImage":"https://images.unsplash.com/photo-1621905251189-08b45d6a269e?auto=format&fit=crop&w=1200&q=80","indexable":true,"canonicalPath":"/hvac"},"privacy":{"pageId":"privacy","title":{"en":"Privacy Policy & Personal Data Protection | HARD Group","ar":"سياسة الخصوصية وحماية البيانات | مجموعة هارد"},"description":{"en":"Official privacy policy and data governance practices of HARD Group in compliance with Saudi PDPL regulations.","ar":"سياسة الخصوصية الرسمية وحماية البيانات الشخصية لمجموعة هارد وفق نظام حماية البيانات الشخصية (PDPL)."},"ogImage":"https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=80","indexable":true,"canonicalPath":"/privacy"},"terms":{"pageId":"terms","title":{"en":"Terms of Service & Operational Conditions | HARD Group","ar":"الشروط والأحكام والضوابط التشغيلية | مجموعة هارد"},"description":{"en":"Operational terms and brokerage advisory conditions governed by REGA License #1200048912 and Saudi laws.","ar":"الشروط والأحكام المعتمدة والضوابط التنظيمية لمجموعة هارد وخدمات الوساطة العقارية المرخصة."},"ogImage":"https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=80","indexable":true,"canonicalPath":"/terms"}}'::jsonb) on conflict(sector,section_key) do nothing;
insert into public.hard_sector_sections(sector,section_key,body) values('realestate','legal','{"privacyPolicy":{"title":{"en":"Privacy Policy & Personal Data Protection Framework","ar":"سياسة الخصوصية وإطار حماية البيانات الشخصية"},"lastUpdated":"2026-10-10","sections":[{"id":"sec-1","heading":{"en":"1. Data Controller Identification & Scope","ar":"1. هوية جهة التحكم ونطاق سياسة الخصوصية"},"body":{"en":"HARD Real Estate Group (Commercial Registration #1111111111, REGA License #1200048912, Al Khobar, Saudi Arabia) acts as the Data Controller under the Saudi Personal Data Protection Law (PDPL). This policy applies to all personal data collected through our web portals.","ar":"تعد شركة هارد للعقارات (السجل التجاري رقم 1111111111 وترخيص الهيئة العامة للعقار رقم 1200048912، الخبر، المملكة العربية السعودية) جهة التحكم بالبيانات وفق نظام حماية البيانات الشخصية (PDPL) بالمملكة."},"isRequired":true},{"id":"sec-2","heading":{"en":"2. Collected Personal Data & Purpose","ar":"2. البيانات الشخصية المجمعة وأغراض المعالجة"},"body":{"en":"We collect client full names, verified phone/WhatsApp numbers, email addresses, and specific property inquiry parameters strictly for facilitating property viewings, issuing non-binding investment offers, and complying with REGA brokerage record-keeping regulations.","ar":"نقوم بجمع أسماء العملاء، أرقام التواصل الموثقة، العناوين البريدية، ومواصفات العقارات المطلوبة حصرياً لغرض تنظيم المعاينات، إعداد عروض الاستثمار، والالتزام بمتطلبات السجلات لدى الهيئة العامة للعقار."},"isRequired":true},{"id":"sec-3","heading":{"en":"3. Data Security, Storage & Cookies","ar":"3. أمن البيانات والتخزين وملفات التعريف (Cookies)"},"body":{"en":"All client communications and submission payloads are transmitted via SSL encryption. Local storage is strictly utilized for UI language preferences and authentication tokens. We do not sell client data to third parties.","ar":"تتم كافة المراسلات عبر تشفير آمن. يُستخدم التخزين المحلي للمتصفح لحفظ تفضيلات اللغة والحرص على حماية البيانات، ولا يتم بيع أو مشاركة بيانات العملاء مع أي طرف ثالث."},"isRequired":true},{"id":"sec-4","heading":{"en":"4. Data Subject Rights & Data Officer Contact","ar":"4. حقوق صاحب البيانات والتواصل مع ضابط الحماية"},"body":{"en":"In accordance with PDPL, you retain the right to request access, correction, or destruction of your personal records. Contact our Privacy Compliance Officer at info@hardgp.com or +966 55 612 5711.","ar":"يحق لك وفق نظام PDPL طلب الاطلاع أو تصحيح أو إتلاف بياناتك الشخصية من سجلاتنا عبر التواصل المباشر مع مسئول حماية البيانات عبر info@hardgp.com أو الهاتف +966 55 612 5711."},"isRequired":true}]},"termsOfService":{"title":{"en":"Terms of Service & Operational Governance","ar":"الشروط والأحكام والضوابط التشغيلية المعتمدة"},"lastUpdated":"2026-10-10","sections":[{"id":"term-1","heading":{"en":"1. Official Regulatory Licensing Identity","ar":"1. التراخيص والتسجيل الرسمي"},"body":{"en":"HARD Real Estate is an officially registered brokerage and real estate services company under REGA License #1200048912 and Commercial Registration #1111111111, operating in Eastern Province, Riyadh, and Jeddah.","ar":"شركة هارد للعقارات هي مؤسسة عقارية ووساطة مرخصة رسمياً من الهيئة العامة للعقار بموجب ترخيص رقم 1200048912 والسجل التجاري رقم 1111111111."},"isRequired":true},{"id":"term-2","heading":{"en":"2. Non-Binding Inquiries & Official Contracting","ar":"2. الاستفسارات غير الملزمة والتعاقد الرسمي"},"body":{"en":"All online inquiry forms, valuation calculators, and brochure requests constitute non-binding consultation requests. Enforceable property transactions occur strictly through notarized contracts executed via approved Saudi government platforms (Ejar, Najiz, Real Estate Exchange).","ar":"تعتبر الاستفسارات الإلكترونية وحسابات التقدير طلبات استشارية غير ملزمة. ينعقد الالتزام القانوني حصرياً عبر توثيق العقود الرسمية بموجب الأنظمة المعتمدة (منصة إيجار، البورصة العقارية، ناجز)."},"isRequired":true},{"id":"term-3","heading":{"en":"3. Accuracy of Listing Specifications & Blueprint Specs","ar":"3. دقة بيانات العقارات والمواصفات المعتمدة"},"body":{"en":"Property dimensions, architectural blueprints, starting prices, and estimated yields are compiled from official engineering blueprints and verified title deeds. Pricing and availability remain subject to final bilateral contract execution.","ar":"يتم تدقيق بيانات المساحات، والمواصفات الإنشائية، والأسعار بناءً على الصكوك والمخططات المعتمدة، وتظل خاضعة للتوافر والتعاقد النهائي."},"isRequired":true}]},"complianceFlags":{"regaLicenseId":"1200048912","commercialRegNum":"1111111111","dataControllerEmail":"info@hardgp.com","isRegaCompliant":true,"isPdplCompliant":true,"missingPolicyFlags":[]}}'::jsonb) on conflict(sector,section_key) do nothing;
